"""두 서버(기준 구현, Rust 구현)를 띄우고 같은 요청을 보내 계약 4절의 규칙으로 응답을 비교하는 공용 도구.

compare.py(정해 둔 케이스)와 fuzz.py(무작위 요청열)가 쓴다.
요청은 http.client 로 직접 만들어 본문 바이트와 헤더를 그대로 보낸다.
"""

from __future__ import annotations

import base64
import http.client
import json
import os
import socket
import subprocess
import sys
import time
from dataclasses import dataclass
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
COMPARED_HEADERS = ("content-type", "location", "allow")


def free_port() -> int:
    with socket.socket() as sock:
        sock.bind(("127.0.0.1", 0))
        return sock.getsockname()[1]


@dataclass
class Server:
    name: str
    port: int
    proc: subprocess.Popen
    conn: http.client.HTTPConnection | None = None

    def request(self, method: str, path: str, body: bytes | None, headers: dict[str, str]) -> tuple[int, dict, bytes]:
        for attempt in range(2):  # 서버가 연결을 닫았으면 한 번 다시 연결
            try:
                if self.conn is None:
                    self.conn = http.client.HTTPConnection("127.0.0.1", self.port, timeout=10)
                self.conn.request(method, path, body=body, headers=headers)
                response = self.conn.getresponse()
                data = response.read()
                found = {k.lower(): v for k, v in response.getheaders()}
                if found.get("connection", "").lower() == "close":
                    self.conn.close()
                    self.conn = None
                return response.status, found, data
            except (ConnectionError, http.client.HTTPException, OSError):
                if self.conn is not None:
                    self.conn.close()
                self.conn = None
                if attempt == 1:
                    raise
        raise RuntimeError("unreachable")

    def stop(self) -> None:
        if self.conn is not None:
            self.conn.close()
        self.proc.terminate()
        try:
            self.proc.wait(timeout=5)
        except subprocess.TimeoutExpired:
            self.proc.kill()


def start(name: str, cmd: list[str]) -> Server:
    port = free_port()
    env = dict(os.environ, STOCKROOM_TEST="1")
    proc = subprocess.Popen([*cmd, "--port", str(port)], cwd=ROOT, env=env,
                            stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    server = Server(name, port, proc)
    deadline = time.monotonic() + 20
    while time.monotonic() < deadline:
        if proc.poll() is not None:
            raise RuntimeError(f"{name} server exited with code {proc.returncode}")
        try:
            if server.request("GET", "/health", None, {})[0] == 200:
                return server
        except OSError:
            time.sleep(0.05)
    server.stop()
    raise RuntimeError(f"{name} server did not answer /health")


def start_pair(rust_binary: Path) -> tuple[Server, Server]:
    python = start("python", [sys.executable, "python_src/run_server.py"])
    try:
        rust = start("rust", [str(rust_binary.resolve())])
    except Exception:
        python.stop()
        raise
    return python, rust


def encode(step: dict) -> tuple[bytes | None, dict[str, str]]:
    headers = dict(step.get("headers", {}))
    if "json" in step:
        headers.setdefault("Content-Type", "application/json")
        return json.dumps(step["json"], ensure_ascii=False, separators=(",", ":")).encode(), headers
    if "body" in step:
        return step["body"].encode("utf-8"), headers
    if "body_b64" in step:
        return base64.b64decode(step["body_b64"]), headers
    return None, headers


def normalize(server: Server, status: int, headers: dict, body: bytes) -> dict:
    out = {"status": status}
    for name in COMPARED_HEADERS:
        if name in headers:
            out[name] = headers[name].replace(f"127.0.0.1:{server.port}", "<host>")
    if status == 422:
        try:
            out["errors"] = [[e["type"], e["loc"]] for e in json.loads(body)["detail"]]
        except (ValueError, KeyError, TypeError):
            out["body"] = body  # 계약 형식이 아니면 바이트 그대로 비교(다르게 나온다)
    else:
        out["body"] = body
    return out


def run_steps(python: Server, rust: Server, steps: list[dict]) -> list[str]:
    """상태를 비운 뒤 요청을 차례로 보내고, 처음 다른 응답에서 멈춘다. 차이가 없으면 빈 목록."""
    for server in (python, rust):
        if server.request("POST", "/_test/reset", None, {})[0] != 204:
            return [f"{server.name}: /_test/reset failed"]
    for index, step in enumerate(steps, 1):
        body, headers = encode(step)
        got = [normalize(s, *s.request(step["method"], step["path"], body, headers)) for s in (python, rust)]
        if got[0] != got[1]:
            label = f"step {index}: {step['method']} {step['path']}"
            diffs = [f"{key}: python={got[0].get(key)!r:.200} rust={got[1].get(key)!r:.200}"
                     for key in sorted(set(got[0]) | set(got[1])) if got[0].get(key) != got[1].get(key)]
            return [label, *diffs]
    return []

"""승인한 기준 구현을 고정하고, 바뀌지 않았는지 검사한다 (03-4).

사용법 (실습 프로젝트 폴더에서):
    uv run --no-project python ../../tools/baseline.py lock    # 사람이 승인할 때 1회
    uv run --no-project python ../../tools/baseline.py check   # 에이전트 작업 전후

lock 은 보호 대상 파일의 SHA-256 을 baseline.lock 에 적는다.
check 는 지금 파일과 baseline.lock 을 비교한다.

종료 코드: 0 = 그대로, 1 = 바뀐 파일 있음, 2 = baseline.lock 없음.
"""

from __future__ import annotations

import hashlib
import sys
from datetime import date
from pathlib import Path

# 사람이 소유하는 것들. 에이전트는 rust_app/ 과 reports/ 만 쓴다
PROTECTED = ["python_src", "tests", "contracts", "automation", ".python-version", "pyproject.toml", "uv.lock"]
LOCK_NAME = "baseline.lock"
SKIP_DIRS = {"__pycache__", ".pytest_cache", ".hypothesis"}


def protected_files(root: Path) -> list[Path]:
    files: list[Path] = []
    for name in PROTECTED:
        path = root / name
        if path.is_file():
            files.append(path)
        elif path.is_dir():
            files.extend(
                p for p in path.rglob("*") if p.is_file() and not SKIP_DIRS.intersection(p.relative_to(root).parts)
            )
    return sorted(files)


def digest(root: Path, path: Path) -> str:
    data = path.read_bytes()
    # git(core.autocrlf)은 체크아웃할 때 텍스트 파일의 줄바꿈을 OS에 맞게 바꾼다.
    # 그래서 줄바꿈을 LF로 맞춘 뒤 해시한다. 단 fixtures 는 바이트 그대로가 계약이므로
    # (.gitattributes 에서 -text) 손대지 않는다
    if "fixtures" not in path.relative_to(root).parts:
        data = data.replace(b"\r\n", b"\n")
    return hashlib.sha256(data).hexdigest()


def snapshot(root: Path) -> dict[str, str]:
    return {p.relative_to(root).as_posix(): digest(root, p) for p in protected_files(root)}


def read_lock(lock: Path) -> dict[str, str]:
    entries: dict[str, str] = {}
    for line in lock.read_text(encoding="utf-8").splitlines():
        if line and not line.startswith("#"):
            sha, rel = line.split("  ", 1)
            entries[rel] = sha
    return entries


def lock(root: Path) -> int:
    current = snapshot(root)
    lines = [f"# approved {date.today().isoformat()} — 이 파일은 사람이 승인할 때만 다시 만든다"]
    lines += [f"{sha}  {rel}" for rel, sha in current.items()]
    (root / LOCK_NAME).write_text("\n".join(lines) + "\n", encoding="utf-8")
    print(f"locked {len(current)} files -> {LOCK_NAME}")
    return 0


def check(root: Path) -> int:
    lock_path = root / LOCK_NAME
    if not lock_path.exists():
        print(f"baseline: {LOCK_NAME} not found. 기준 구현이 아직 승인되지 않았습니다", file=sys.stderr)
        return 2
    locked, current = read_lock(lock_path), snapshot(root)
    problems = [f"changed: {rel}" for rel in locked if rel in current and current[rel] != locked[rel]]
    problems += [f"removed: {rel}" for rel in locked if rel not in current]
    problems += [f"added:   {rel}" for rel in current if rel not in locked]
    for problem in problems:
        print(f"baseline: {problem}", file=sys.stderr)
    if problems:
        return 1
    print(f"baseline OK ({len(locked)} files)")
    return 0


def main(argv: list[str]) -> int:
    if len(argv) != 1 or argv[0] not in ("lock", "check"):
        print("usage: baseline.py lock|check", file=sys.stderr)
        return 2
    root = Path.cwd()
    return lock(root) if argv[0] == "lock" else check(root)


