    }

    fn parse_object(&mut self, idx: usize) -> Result<(Value, usize), Fail> {
        let mut pairs: Vec<(PyStr, Value)> = Vec::new();
        let mut idx = self.skip_ws(idx);
        if self.at(idx) == Some('}' as u32) {
