    fn url_helpers() {
        assert_eq!(unquote(b"%41%zz%e9%2"), "A%zz\u{fffd}%2");
        assert_eq!(
            parse_qsl(b"a=1&&b&c=x+y=z"),
            [
                ("a".into(), "1".into()),
                ("b".into(), "".into()),
                ("c".into(), "x y=z".into())
            ]
        );
        let local: SocketAddr = "127.0.0.1:8000".parse().unwrap();
        assert_eq!(
            redirect_location("/items é", b"limit=1", Some("testserver"), local),
