        );
        assert_eq!(
            redirect_location("/items", b"", Some("bad host"), local),
            "http://127.0.0.1:8000/items"
        );
        assert_eq!(
            redirect_location("/items", b"", Some("[::1]:99"), local),
            "http://[::1]:99/items"
        );
    }
}

