    !s.is_empty()
        && s.iter()
            .all(|&c| c.is_ascii_alphanumeric() || b"!#$%&'*+-.^_`|~".contains(&c))
}

fn read_request(reader: &mut impl BufRead) -> Result<Parsed, ReadError> {
