    let lengths = values("content-length");
    let body = if !transfer.is_empty() {
        if transfer.len() != 1 || !transfer[0].eq_ignore_ascii_case(b"chunked") {
            return Err(ReadError::Invalid);
        }
        read_chunked(reader)?
