        let first = lengths[0];
        if lengths.iter().any(|v| *v != first)
            || first.is_empty()
            || !first.iter().all(u8::is_ascii_digit)
        {
            return Err(ReadError::Invalid);
        }
        let length: usize = std::str::from_utf8(first)
            .ok()
            .and_then(|s| s.parse().ok())
            .ok_or(ReadError::Invalid)?;
        let mut body = vec![0; length];
        reader.read_exact(&mut body)?;
        body
    } else {
        Vec::new()
    };
    Ok(Parsed {
        method: String::from_utf8_lossy(method).into_owned(),
        target: target.to_vec(),
        headers,
        body,
        keep_alive: http11 && !close,
    })
}

fn read_chunked(reader: &mut impl BufRead) -> Result<Vec<u8>, ReadError> {
    let mut body = Vec::new();
    loop {
        let mut budget = MAX_HEAD;
        let line = read_line(reader, &mut budget)?;
        let size_text = line.split(|&c| c == b';').next().unwrap_or(&[]).trim_ascii();
        let size = std::str::from_utf8(size_text)
            .ok()
