//! stockroom: 재고 관리 API (python_src/stockroom/app.py 의 Rust 이식).
//!
//! 사용법: stockroom [--host HOST] [--port PORT]   (기본 127.0.0.1:8000)

mod handlers;
mod http;
mod jsonout;
mod lax;
mod models;
mod pyjson;
mod router;
mod store;

use std::net::TcpListener;
use std::process::ExitCode;
use std::sync::Arc;

const USAGE: &str = "usage: stockroom [-h] [--host HOST] [--port PORT]";

struct Args {
    host: String,
    port: u16,
}

fn usage_error(message: &str) -> ExitCode {
    eprintln!("{USAGE}\nstockroom: error: {message}");
    ExitCode::from(2)
}

/// argparse 처럼 `--host H`, `--host=H`, 모호하지 않은 접두 약어(`--po`)를 받는다
fn parse_args(raw: &[String]) -> Result<Option<Args>, String> {
    let mut args = Args {
        host: "127.0.0.1".into(),
        port: 8000,
    };
    let mut i = 0;
    while i < raw.len() {
        let arg = &raw[i];
        if arg == "-h" {
            return Ok(None);
        }
        let Some(long) = arg.strip_prefix("--").filter(|s| !s.is_empty()) else {
            return Err(format!("unrecognized arguments: {arg}"));
        };
        let (name, inline) = match long.split_once('=') {
            Some((n, v)) => (n, Some(v.to_string())),
            None => (long, None),
        };
        let options = ["help", "host", "port"];
        let chosen = match options.iter().find(|o| **o == name) {
            Some(exact) => *exact,
            None => {
                let found: Vec<&str> = options
                    .iter()
                    .copied()
                    .filter(|o| o.starts_with(name))
                    .collect();
                match found[..] {
                    [one] => one,
                    [] => return Err(format!("unrecognized arguments: {arg}")),
                    _ => return Err(format!("ambiguous option: --{name}")),
                }
            }
        };
        if chosen == "help" {
            return Ok(None);
        }
        let value = match inline {
            Some(v) => v,
            None => {
                i += 1;
                raw.get(i)
                    .cloned()
                    .ok_or_else(|| format!("argument --{chosen}: expected one argument"))?
            }
        };
        if chosen == "host" {
            args.host = value;
        } else {
            args.port = value
                .trim()
                .parse()
                .map_err(|_| format!("argument --port: invalid int value: '{value}'"))?;
        }
        i += 1;
    }
    Ok(Some(args))
}

fn main() -> ExitCode {
    let raw: Vec<String> = std::env::args().skip(1).collect();
    let args = match parse_args(&raw) {
        Ok(Some(args)) => args,
        Ok(None) => {
            println!("{USAGE}");
            return ExitCode::SUCCESS;
        }
        Err(message) => return usage_error(&message),
    };
    let test_mode = std::env::var("STOCKROOM_TEST").as_deref() == Ok("1");
    let listener = match TcpListener::bind((args.host.as_str(), args.port)) {
        Ok(listener) => listener,
        Err(err) => {
            eprintln!("stockroom: cannot bind {}:{}: {err}", args.host, args.port);
            return ExitCode::from(1);
        }
    };
    http::serve(listener, Arc::new(handlers::App::new(test_mode)));
    ExitCode::SUCCESS
}

#[cfg(test)]
mod tests {
    use super::*;

    fn parse(args: &[&str]) -> Result<Option<Args>, String> {
        parse_args(&args.iter().map(|s| s.to_string()).collect::<Vec<_>>())
    }

    #[test]
    fn arguments_like_argparse() {
        let args = parse(&["--port", "9000", "--host=0.0.0.0"]).unwrap().unwrap();
        assert_eq!((args.host.as_str(), args.port), ("0.0.0.0", 9000));
        assert_eq!(parse(&["--po=81"]).unwrap().unwrap().port, 81);
        assert!(parse(&["--h", "x"]).is_err());
        assert!(parse(&["--port", "x"]).is_err());
        assert!(parse(&["--help"]).unwrap().is_none());
    }
}

