fn decode_utf16(b: &[u8], big_endian: bool) -> Option<Vec<u32>> {
    if b.len() % 2 != 0 {
        return None;
    }
    let units: Vec<u32> = b
        .chunks_exact(2)
        .map(|p| {
            if big_endian {
                u16::from_be_bytes([p[0], p[1]]) as u32
            } else {
                u16::from_le_bytes([p[0], p[1]]) as u32
            }
        })
        .collect();
    let mut out = Vec::with_capacity(units.len());
    let mut i = 0;
    while i < units.len() {
        let u = units[i];
        if (0xD800..0xDC00).contains(&u) {
            if let Some(&low) = units.get(i + 1) {
                if (0xDC00..0xE000).contains(&low) {
                    out.push(0x10000 + ((u - 0xD800) << 10) + (low - 0xDC00));
                    i += 2;
                    continue;
                }
            }
        }
        out.push(u);
        i += 1;
    }
    Some(out)
}

fn decode_utf32(b: &[u8], big_endian: bool) -> Option<Vec<u32>> {
    if b.len() % 4 != 0 {
        return None;
    }
    b.chunks_exact(4)
        .map(|p| {
            let c = if big_endian {
                u32::from_be_bytes([p[0], p[1], p[2], p[3]])
            } else {
                u32::from_le_bytes([p[0], p[1], p[2], p[3]])
            };
            (c < 0x110000).then_some(c)
        })
        .collect()
}

