    loop {
        let line = read_line(reader, &mut budget).map_err(|e| match e {
            ReadError::Closed => ReadError::Invalid,
            other => other,
        })?;
        if line.is_empty() {
            break;
        }
        let colon = line
            .iter()
            .position(|&c| c == b':')
            .ok_or(ReadError::Invalid)?;
