/// argparse 처럼 `--host H`, `--host=H`, 모호하지 않은 접두 약어(`--po`)를 받는다
fn parse_args(raw: &[String]) -> Result<Option<Args>, String> {
    let mut args = Args {
        host: "127.0.0.1".into(),
        port: 8000,
    };
    let mut i = 0;
    while i < raw.len() {
        let arg = &raw[i];
